// The roster. A community that claims 64 members should have 64 people in
// it, with names. The host console is the only surface that ever sees this
// list — members never do. Generated once and checked in, so ids, avatars
// and histories never shift underfoot.

export type MemberRole = 'owner' | 'admin' | 'member'

export interface Member {
  personId: string
  communityId: string
  role: MemberRole
  joinedLabel: string // "Mar 2025"
  monthsIn: number
  attended: number
  noShows: number
  lastSeenLabel: string
  lastSeenWeeks: number // so the column can actually sort
}

